/* My Trees manages scoped diagrams; World remains the single graph renderer/registry UI. */
const TreesUI={
 labels:{family:'Family Tree',hierarchy:'Hierarchy',blank:'Blank Tree'},
 async commit(change){return World.commit(change)},
 dialog(title,fields,save){const dialog=$('#treeDialog');dialog.innerHTML='<form id="treeForm"><div class="world-dialog-heading"><h2>'+escapeHTML(title)+'</h2><button type="button" data-tree-cancel aria-label="Close tree dialog">×</button></div>'+fields+'<p id="treeFormError" role="alert"></p><div class="dialog-actions"><button type="button" data-tree-cancel>Cancel</button><button type="submit" class="primary">Save</button></div></form>';dialog.showModal();dialog.querySelectorAll('[data-tree-cancel]').forEach(b=>b.onclick=()=>dialog.close());$('#treeForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;$('#treeFormError').textContent='';try{await save(e.currentTarget);dialog.close()}catch(e){$('#treeFormError').textContent=e.message}finally{button.disabled=false}}},
 overview(){const trees=TreeModel.list(World.book());$('#worldPanel').innerHTML='<div class="world-tools">'+World.mapNavigation()+'<button id="newTree">＋ New Tree</button></div><div id="treeCollection">'+(!trees.length?'<p class="tree-empty">Create a tree to organize a family, sect, or fictional world.</p>':trees.map(t=>'<article class="tree-entry" data-tree="'+escapeHTML(t.id)+'"><div><h2>'+escapeHTML(t.name)+'</h2><small>'+this.labels[t.template]+' · '+t.memberIds.length+' members</small>'+(t.description?'<p>'+escapeHTML(t.description)+'</p>':'')+'</div><div class="tree-entry-actions"><button data-open-tree="'+t.id+'">Open</button><button data-edit-tree="'+t.id+'">Rename / Edit</button><button data-copy-tree="'+t.id+'">Duplicate</button><button data-delete-tree="'+t.id+'">Delete</button></div></article>').join(''))+'</div>';World.bindSections();$('#newTree').onclick=()=>this.edit();$('#worldPanel').querySelectorAll('[data-open-tree]').forEach(b=>b.onclick=()=>World.switchMap('trees',b.dataset.openTree));$('#worldPanel').querySelectorAll('[data-edit-tree]').forEach(b=>b.onclick=()=>this.edit(b.dataset.editTree));$('#worldPanel').querySelectorAll('[data-copy-tree]').forEach(b=>b.onclick=async()=>{try{await this.commit(book=>TreeModel.duplicate(book,b.dataset.copyTree))}catch(e){serious(e)}});$('#worldPanel').querySelectorAll('[data-delete-tree]').forEach(b=>b.onclick=()=>this.remove(b.dataset.deleteTree))},
 edit(id=null){const tree=id?TreeModel.get(World.book(),id):null,w=World.data();this.dialog(tree?'Edit Tree':'New Tree','<label>Tree Name<input name="name" required maxlength="200" value="'+escapeHTML(tree?.name||'')+'"></label><label>Template<select name="template">'+Object.entries(this.labels).map(([value,label])=>'<option value="'+value+'" '+(tree?.template===value?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label>Description — optional<textarea name="description" rows="2">'+escapeHTML(tree?.description||'')+'</textarea></label><label>Linked organization — optional<select name="linkedOrganizationId"><option value="">None</option>'+w.organizations.map(o=>'<option value="'+o.id+'" '+(tree?.linkedOrganizationId===o.id?'selected':'')+'>'+escapeHTML(o.name)+'</option>').join('')+'</select></label><p class="helper">Templates never add members automatically. Linking an organization does not import its characters.</p>',async form=>{const data={name:form.elements.name.value.trim(),template:form.elements.template.value,description:form.elements.description.value,linkedOrganizationId:form.elements.linkedOrganizationId.value||null};let saved=id;await this.commit(book=>{const next=id?TreeModel.update(book,id,data):TreeModel.create(book,data);saved=id||next.world.trees.at(-1).id;return next});if(!id)await World.switchMap('trees',saved)})},
 async remove(id){if(!confirm('Delete this tree? Global characters, relationships and Story Board cards will be kept.'))return;try{await World.flushSave();await this.commit(book=>TreeModel.remove(book,id));if(World.settings.treeId===id){World.settings.treeId=null;World.render();World.saveSettings()}}catch(e){serious(e)}},
 graphActions(t){return '<button id="backToTrees">← My Trees</button><span class="tree-context" title="'+escapeHTML(t.name)+'">'+escapeHTML(t.name)+' <small>'+this.labels[t.template]+'</small></span><button id="addTreeMember">＋ Add Member</button><button id="newRelationship">＋ Relationship</button>'+(t.template==='blank'?'<button id="newLocalConnection">＋ Local Connection</button>':'')+'<input id="worldSearch" aria-label="Search registry" placeholder="Search tree members…" value="'+escapeHTML(World.settings.query||'')+'"><details class="world-more"><summary>Tree tools</summary><div><button id="editCurrentTree">Rename / Edit</button>'+(t.template==='hierarchy'?'<button id="editTreeRanks">Edit Ranks</button>':'')+'<button id="deleteCurrentTree">Delete Tree</button><select id="worldOrganization" hidden><option value=""></option></select><select id="worldType" aria-label="Filter relationship type"><option value="">All relationships</option>'+Object.entries(WorldModel.presets).map(([key,label])=>'<option value="'+key+'" '+(World.settings.type===key?'selected':'')+'>'+label+'</option>').join('')+'</select><p>Only explicitly added members appear. Family and Hierarchy keep their vertical structure. Blank Trees allow free placement.</p></div></details>'},
 bindGraph(t){$('#backToTrees').onclick=()=>World.switchMap('trees');$('#addTreeMember').onclick=()=>this.members(t.id);$('#editCurrentTree').onclick=()=>this.edit(t.id);$('#deleteCurrentTree').onclick=()=>this.remove(t.id);$('#editTreeRanks')?.addEventListener('click',()=>this.ranks(t.id));$('#newLocalConnection')?.addEventListener('click',()=>this.local(t.id))},
 members(id){let selected=new Set();this.dialog('Add Members','<label>Search Character Registry<input id="treeMemberSearch" autocomplete="off"></label><div id="treeMemberChoices"></div><details><summary>Create a missing character</summary><label>Name<input id="newTreeMemberName" maxlength="200"></label><button type="button" id="createTreeMember">Create & select</button><p id="treeMemberNotice" aria-live="polite"></p></details><p class="helper">Only selected characters will be added to this tree. A character can belong to several trees.</p>',async()=>{await this.commit(book=>TreeModel.add(book,id,[...selected]));World.draw();World.inspect()});
  const render=()=>{const q=$('#treeMemberSearch').value.trim().toLowerCase(),t=TreeModel.get(World.book(),id);$('#treeMemberChoices').innerHTML=World.data().characters.filter(c=>(c.name+' '+(c.aliases||[]).join(' ')).toLowerCase().includes(q)).map(c=>'<label class="checkbox-label"><input type="checkbox" data-add-member="'+c.id+'" '+(t.memberIds.includes(c.id)?'checked disabled':selected.has(c.id)?'checked':'')+'>'+escapeHTML(c.name)+(t.memberIds.includes(c.id)?' · already added':'')+'</label>').join('')||'<p>No matching characters.</p>';$('#treeMemberChoices').querySelectorAll('[data-add-member]').forEach(input=>input.onchange=()=>input.checked?selected.add(input.dataset.addMember):selected.delete(input.dataset.addMember))};$('#treeMemberSearch').oninput=render;render();$('#newTreeMemberName').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#createTreeMember').click()}};$('#createTreeMember').onclick=async()=>{const name=$('#newTreeMemberName').value.trim();if(!name)return;const matches=World.data().characters.filter(c=>c.name.toLowerCase()===name.toLowerCase());if(matches.length){$('#treeMemberSearch').value=name;$('#treeMemberNotice').textContent='Matching characters already exist. Select one from the registry list above; no automatic merge or duplicate was created.';render();return}let created;try{await this.commit(book=>{const next=WorldModel.character(book,{name});created=next.world.characters.at(-1).id;return next});selected.add(created);$('#treeMemberSearch').value='';$('#newTreeMemberName').value='';$('#treeMemberNotice').textContent='Created and selected. Save to add this character to the tree.';render()}catch(e){$('#treeFormError').textContent=e.message}}},
 ranks(id){const tree=TreeModel.get(World.book(),id);let ranks=structuredClone(tree.ranks||[]),assignments={...tree.assignments};this.dialog('Tree Ranks','<p class="helper">Ranks and assignments apply to this tree. Shared organization memberships remain unchanged.</p><div id="treeRankRows"></div><label>New Rank<input id="newRankName" maxlength="120"></label><button type="button" id="addTreeRank">＋ Rank</button>'+(tree.linkedOrganizationId?'<button type="button" id="copyOrganizationRanks">Add linked organization ranks</button>':'')+'<h3>Member assignments</h3><div id="treeRankAssignments"></div>',async()=>{await this.commit(book=>TreeModel.update(book,id,{ranks,assignments}))});
  const draw=()=>{$('#treeRankRows').innerHTML=ranks.map((r,i)=>'<div class="tree-rank-row"><input aria-label="Rank name '+(i+1)+'" data-rank-name="'+r.id+'" value="'+escapeHTML(r.name)+'"><button type="button" data-rank-up="'+r.id+'" aria-label="Move rank up" '+(!i?'disabled':'')+'>↑</button><button type="button" data-rank-down="'+r.id+'" aria-label="Move rank down" '+(i===ranks.length-1?'disabled':'')+'>↓</button><button type="button" data-rank-remove="'+r.id+'">Remove unused</button></div>').join('');$('#treeRankRows').querySelectorAll('[data-rank-name]').forEach(input=>input.oninput=()=>{ranks.find(r=>r.id===input.dataset.rankName).name=input.value});for(const [key,delta] of [['rankUp',-1],['rankDown',1]])$('#treeRankRows').querySelectorAll('[data-'+(delta<0?'rank-up':'rank-down')+']').forEach(b=>b.onclick=()=>{const i=ranks.findIndex(r=>r.id===b.dataset[key]),j=i+delta;if(j<0||j>=ranks.length)return;[ranks[i],ranks[j]]=[ranks[j],ranks[i]];draw()});$('#treeRankRows').querySelectorAll('[data-rank-remove]').forEach(b=>b.onclick=()=>{if(Object.values(assignments).includes(b.dataset.rankRemove)){$('#treeFormError').textContent='Reassign members before removing a used rank.';return}ranks=ranks.filter(r=>r.id!==b.dataset.rankRemove);draw()});$('#treeRankAssignments').innerHTML=World.data().characters.filter(c=>tree.memberIds.includes(c.id)).map(c=>'<label>'+escapeHTML(c.name)+'<select data-tree-rank="'+c.id+'"><option value="">Unassigned</option>'+ranks.map(r=>'<option value="'+r.id+'" '+(assignments[c.id]===r.id?'selected':'')+'>'+escapeHTML(r.name)+'</option>').join('')+'</select></label>').join('');$('#treeRankAssignments').querySelectorAll('[data-tree-rank]').forEach(select=>select.onchange=()=>assignments[select.dataset.treeRank]=select.value||null)};
  $('#addTreeRank').onclick=()=>{const name=$('#newRankName').value.trim();if(name){ranks.push({id:crypto.randomUUID(),name});$('#newRankName').value='';draw()}};$('#newRankName').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#addTreeRank').click()}};$('#copyOrganizationRanks')?.addEventListener('click',()=>{for(const r of World.data().organizations.find(o=>o.id===tree.linkedOrganizationId)?.ranks||[])if(!ranks.some(x=>x.name===r.name))ranks.push({id:crypto.randomUUID(),name:r.name});draw()});draw()},
 augmentInspector(t,characterId){const target=$('#worldInspector');target.insertAdjacentHTML('beforeend','<section class="tree-membership"><h3>'+escapeHTML(t.name)+'</h3>'+(t.template==='hierarchy'?'<label>Tree Rank<select id="treeMemberRank"><option value="">Unassigned</option>'+t.ranks.map(r=>'<option value="'+r.id+'" '+(t.assignments?.[characterId]===r.id?'selected':'')+'>'+escapeHTML(r.name)+'</option>').join('')+'</select></label>':'')+'<button id="removeTreeMember">Remove from Tree</button><p>Removal keeps the shared character and global relationships.</p></section>');$('#removeTreeMember').onclick=async()=>{try{await this.commit(book=>TreeModel.removeMember(book,t.id,characterId));World.selected=null;World.draw();World.inspect()}catch(e){serious(e)}};$('#treeMemberRank')?.addEventListener('change',async e=>{try{await this.commit(book=>TreeModel.assign(book,t.id,characterId,e.target.value))}catch(e){serious(e)}});$('#deleteWorldEntity').textContent='Delete Character Globally'},
 local(treeId,id=null,from=''){const t=TreeModel.get(World.book(),treeId),old=t.connections.find(c=>c.id===id),r=old||{from,to:'',label:'',notes:'',directional:false},options=value=>'<option value="">Choose member</option>'+World.data().characters.filter(c=>t.memberIds.includes(c.id)).map(c=>'<option value="'+c.id+'" '+(c.id===value?'selected':'')+'>'+escapeHTML(c.name)+'</option>').join('');this.dialog(old?'Edit Local Connection':'Local Connection','<p class="helper">Visual connection for this Blank Tree only. This does not create a global character fact.</p><label>From<select name="from" required>'+options(r.from)+'</select></label><label>To<select name="to" required>'+options(r.to)+'</select></label><label>Label<input name="label" maxlength="200" value="'+escapeHTML(r.label)+'"></label><label>Notes<textarea name="notes" rows="2">'+escapeHTML(r.notes||'')+'</textarea></label><label class="checkbox-label"><input type="checkbox" name="directional" '+(r.directional?'checked':'')+'> Directional arrow</label>',async form=>{let saved=id;await this.commit(book=>{const next=TreeModel.connection(book,treeId,{from:form.elements.from.value,to:form.elements.to.value,label:form.elements.label.value,notes:form.elements.notes.value,directional:form.elements.directional.checked},id);saved=id||TreeModel.get(next,treeId).connections.at(-1).id;return next});World.selected={kind:'relationship',id:'tree-local:'+saved};World.inspect()})},
 inspectLocal(t,id){const c=t.connections.find(c=>c.id===id),target=$('#worldInspector');if(!c){target.hidden=true;return}target.hidden=false;target.innerHTML='<button id="closeWorldInspector" aria-label="Close profile">×</button><h2>'+escapeHTML(c.label)+'</h2><p>Tree-local visual connection</p><p>'+escapeHTML(WorldModel.name(World.data(),'c:'+c.from)+(c.directional?' → ':' ↔ ')+WorldModel.name(World.data(),'c:'+c.to))+'</p><p>'+escapeHTML(c.notes||'')+'</p><button id="editLocalConnection">Edit Connection</button><button id="removeLocalConnection">Remove Connection</button>';$('#closeWorldInspector').onclick=()=>{World.selected=null;World.inspect()};$('#editLocalConnection').onclick=()=>this.local(t.id,id);$('#removeLocalConnection').onclick=async()=>{if(confirm('Remove this tree-local connection? Global relationships are unchanged.')){await this.commit(book=>TreeModel.removeConnection(book,t.id,id));World.selected=null;World.inspect()}}}
};
document.body.insertAdjacentHTML('beforeend','<dialog id="treeDialog"></dialog>');
